import os,re,json
from collections import Counter
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()
def f(g):
    H,W=len(g),len(g[0])
    bg=Counter(x for r in g for x in r).most_common(1)[0][0]
    bycolor={}
    for r in range(H):
        for c in range(W):
            if g[r][c]!=bg: bycolor.setdefault(g[r][c],[]).append((r,c))
    anchor=None
    for x,cs in bycolor.items():
        rs=[p[0] for p in cs]; cl=[p[1] for p in cs]
        if len(cs)==(max(rs)-min(rs)+1)*(max(cl)-min(cl)+1):
            anchor=x; break
    cy=(max([p[0] for p in bycolor[anchor]])+min([p[0] for p in bycolor[anchor]]))/2
    cx=(max([p[1] for p in bycolor[anchor]])+min([p[1] for p in bycolor[anchor]]))/2
    res=[row[:] for row in g]
    for x,cs in bycolor.items():
        if x==anchor: continue
        for r,c in cs:
            imgs=[(r,c),(r,int(2*cx)-c),(int(2*cy)-r,c),(int(2*cy)-r,int(2*cx)-c)]
            for rr,cc in imgs:
                if 0<=rr<H and 0<=cc<W and g[rr][cc]==bg:
                    res[rr][cc]=x
    return res
